Exit code: 0
Wall time: 0 seconds
Output:
`default_nettype none
`include "defines.sv"

// free input variables, can take any value each cycle as long as the `assume` are satisfied
module testbench (
	input check,
	input clock, reset
);
	`RVFI_WIRES
	`RVFI_BUS_WIRES

	`RISCV_FORMAL_CHECKER checker_inst (
		.clock  (clock),
		.reset  (reset),
		.check   (check),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

	// Ignore rvfi_order loopback, otherwise the check might be invalid.
	reg rvfi_order_loopback;
	always @(posedge clock) begin
		if (reset) begin
			rvfi_order_loopback <= 0;
		end else if (rvfi_valid && rvfi_order == {64{1'b1}}) begin
			rvfi_order_loopback <= 1;
		end
	end
	always_comb assume (!(rvfi_order_loopback && check));

	rvfi_wrapper wrapper (
		.clock (clock),
		.reset (reset),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

/// Helper Assertion Begin
	// Helper decode for the instruction under check (ADD).
	wire h_is_add = (rvfi_insn[6:0] == 7'b0110011) &&
	                (rvfi_insn[14:12] == 3'b000) &&
	                (rvfi_insn[31:25] == 7'b0000000);
	wire h_dbg_is_add = (wrapper.uut.dbg_insn_opcode[6:0] == 7'b0110011) &&
	                    (wrapper.uut.dbg_insn_opcode[14:12] == 3'b000) &&
	                    (wrapper.uut.dbg_insn_opcode[31:25] == 7'b0000000);

	always @(posedge clock) begin
		if (!reset) begin
			// If the instruction decodes as ADD, it must not be reported as a trap/halt.
			h_add_no_trap: assert(!(rvfi_valid[0] && h_is_add) || !rvfi_trap[0]);
			h_add_no_halt: assert(!(rvfi_valid[0] && h_is_add) || !rvfi_halt[0]);

			// For ADD, the retiring instruction must have captured both source operands.
			h_add_src_captured: assert(!(wrapper.uut.cpuregs_write && h_dbg_is_add) ||
			                           (wrapper.uut.dbg_rs1val_valid && wrapper.uut.dbg_rs2val_valid));
			// For ADD, if a source register is x0 then the captured value must be zero.
			h_add_rs1_x0_val: assert(!(wrapper.uut.cpuregs_write && h_dbg_is_add && (wrapper.uut.dbg_insn_opcode[19:15] == 5'd0)) ||
			                         (wrapper.uut.dbg_rs1val == 0));
			h_add_rs2_x0_val: assert(!(wrapper.uut.cpuregs_write && h_dbg_is_add && (wrapper.uut.dbg_insn_opcode[24:20] == 5'd0)) ||
			                         (wrapper.uut.dbg_rs2val == 0));
			// For ADD, the core decode must reflect an ADD (not just "not SUB").
			h_add_instr_flag: assert(!(wrapper.uut.cpuregs_write && h_dbg_is_add) || wrapper.uut.instr_add);
			// For ADD, the retiring writeback data must match the captured operands.
			h_add_wrdata_match: assert(!(wrapper.uut.cpuregs_write && h_dbg_is_add) ||
			                           (wrapper.uut.cpuregs_wrdata == (wrapper.uut.dbg_rs1val + wrapper.uut.dbg_rs2val)));
			// ADD must not be treated as a control-flow change at retirement.
			h_add_no_branch: assert(!(wrapper.uut.cpuregs_write && h_dbg_is_add) || !wrapper.uut.latched_branch);
			// ADD must not be executed as SUB.
			h_add_not_sub: assert(!(wrapper.uut.cpuregs_write && h_dbg_is_add) || !wrapper.uut.instr_sub);
			// If the retired instruction has no rd, the reported writeback data must be zero.
			h_rd_addr0_wdata0: assert(!(rvfi_valid[0] && (rvfi_rd_addr[4:0] == 5'd0)) || (rvfi_rd_wdata == 0));
			// For 32-bit ADD, RVFI addresses must match the instruction fields.
			h_add_rd_addr_match:  assert(!(rvfi_valid[0] && h_is_add) || (rvfi_rd_addr[4:0]  == rvfi_insn[11:7]));
			h_add_rs1_addr_match: assert(!(rvfi_valid[0] && h_is_add) || (rvfi_rs1_addr[4:0] == rvfi_insn[19:15]));
			h_add_rs2_addr_match: assert(!(rvfi_valid[0] && h_is_add) || (rvfi_rs2_addr[4:0] == rvfi_insn[24:20]));
		end
	end

/// Helper Assertion End
endmodule

